rule "Self Monitoring Logs - Parser GRAYLOG"
when
    grok("^%{TIMESTAMP_ISO8601}", to_string($message.message)).matches == true

then
    let mymessage = multi_grok(
        value: to_string($message.message), 
        patterns: [
            "^%{TIMESTAMP_ISO8601:event_created}%{SPACE}%{LOGLEVEL:event_severity}\\s*\\:%{SPACE}%{NOTSPACE:application_component}%{SPACE}\\-%{SPACE}%{DATA:message}$" //WEBSERVER
            "^%{TIMESTAMP_ISO8601:event_created}%{SPACE}%{LOGLEVEL:event_severity}%{SPACE}\\[%{DATA}\\]%{SPACE}\\[%{DATA}\\]%{SPACE}\\[%{DATA}\\]%{SPACE}\\[%{NOTSPACE:application_component}%{SPACE}\\]%{SPACE}\\[%{DATA:application_hostname}\\]%{SPACE}%{DATA:message}$" //DATANODE
        ],
        only_named_captures: true
    );

    set_field("application_name", "graylog");
    set_field("full_message", to_string($message.message));

    set_fields(mymessage);

    set_field("event_created", to_date(flex_parse_date(to_string($message.event_created))));

    remove_multiple_fields(
        pattern: "^filebeat_.*"
    );

end
